mapper.select:
SELECT * FROM ( SELECT a.ACCOUNT_ID, a.ACCOUNT_NAME, a.EMAIL, a.PHONE_NUMBER, a.ACCOUNT_ROLE, a.SOCIAL_TYPE, a.REG_DATE, (SELECT COUNT(*) FROM REVIEWS WHERE ACCOUNT_ID = a.ACCOUNT_ID) AS REVIEW_COUNT, (SELECT COUNT(*) FROM USER_EVENTS WHERE ACCOUNT_ID = a.ACCOUNT_ID) AS EVENT_COUNT, ROW_NUMBER() OVER (ORDER BY a.REG_DATE DESC) AS RN FROM ACCOUNT_TBL a
AND (a.ACCOUNT_ID LIKE '%' || #{search} || '%' OR a.ACCOUNT_NAME LIKE '%' || #{search} || '%' OR a.EMAIL LIKE '%' || #{search} || '%')
) WHERE RN BETWEEN (#{page} * #{size} + 1) AND ((#{page} + 1) * #{size})

mapper.update:
UPDATE ACCOUNT_TBL
SET ACCOUNT_ROLE = #{role}
WHERE ACCOUNT_ID = #{accountId}

mapper.select:
SELECT * FROM ( SELECT r.REVIEW_ID, r.ACCOUNT_ID, a.ACCOUNT_NAME, r.PLACE_ID, r.PLACE_TYPE, CASE WHEN r.PLACE_TYPE = 'FOOD' THEN (SELECT TITLE FROM RESTAURANTS_DETAIL WHERE ID = r.PLACE_ID) WHEN r.PLACE_TYPE = 'STAY' THEN (SELECT TITLE FROM STAY_DETAIL WHERE CONTENT_ID = r.PLACE_ID) WHEN r.PLACE_TYPE = 'TOUR' THEN (SELECT TITLE FROM TOUR_SPOTS WHERE SPOT_ID = TO_NUMBER(REGEXP_REPLACE(r.PLACE_ID, '[^0-9]', ''))) ELSE r.PLACE_ID END AS PLACE_NAME, r.CONTENT, r.CREATED_AT, r.UPDATED_AT, ROW_NUMBER() OVER (ORDER BY r.CREATED_AT DESC) AS RN FROM REVIEWS r INNER JOIN ACCOUNT_TBL a ON r.ACCOUNT_ID = a.ACCOUNT_ID
AND (r.CONTENT LIKE '%' || #{search} || '%' OR a.ACCOUNT_NAME LIKE '%' || #{search} || '%' OR r.PLACE_ID LIKE '%' || #{search} || '%')
) WHERE RN BETWEEN (#{page} * #{size} + 1) AND ((#{page} + 1) * #{size})

mapper.update:
UPDATE REVIEWS
SET UPDATED_AT = SYSDATE
WHERE REVIEW_ID = #{reviewId}

mapper.select:
SELECT * FROM ( SELECT i.INQUIRY_ID, i.WRITER_ID, w.ACCOUNT_NAME AS WRITER_NAME, i.TITLE, i.CONTENT, i.ANSWER_CONTENT, i.ANSWERER_ID, a.ACCOUNT_NAME AS ANSWERER_NAME, i.STATUS, i.CREATED_DATE, i.ANSWERED_DATE, ROW_NUMBER() OVER (ORDER BY i.CREATED_DATE DESC) AS RN FROM INQUIRIES i LEFT JOIN ACCOUNT_TBL w ON i.WRITER_ID = w.ACCOUNT_ID LEFT JOIN ACCOUNT_TBL a ON i.ANSWERER_ID = a.ACCOUNT_ID
AND i.STATUS = #{status}
) WHERE RN BETWEEN (#{page} * #{size} + 1) AND ((#{page} + 1) * #{size})

SELECT COUNT(*)
FROM INQUIRIES


        AND STATUS = #{status}
